# English publication adaptation of a historical script; no experiment or adjudication was rerun.
from pathlib import Path
import csv, json, collections
P = Path(__file__).resolve().parent

def read(name):
    return list(csv.DictReader((P / name).open(encoding='utf-8-sig')))

def table(head, rows):
    return '\n'.join(['| ' + ' | '.join(head) + ' |', '| ' + ' | '.join(['---'] * len(head)) + ' |'] + ['| ' + ' | '.join(map(str, r)) + ' |' for r in rows])

def pct(x):
    return f'{float(x) * 100:.2f}'

def num(x):
    return f'{float(x):.2f}'

def ci(row, key, lo, hi):
    return f'{pct(row[key])} [{pct(row[lo])}, {pct(row[hi])}]'
s = json.loads((P / 'analysis_summary.json').read_text(encoding='utf-8'))
est = read('estimates_and_audit_uncertainty.csv')
cond = read('condition_question_macro.csv')
pairs = read('paired_condition_differences.csv')
layers = read('observed_and_expanded_counts.csv')
agree = read('simple_proxy_agreement.csv')
bounds = read('unreviewed_worst_case_bounds.csv')
allocation = read('sampling_allocation.csv')
metrics = ['CSR', 'ESS', 'VSSR', 'AA']
labels = {'CSR': 'Complete equivalent expression CSR', 'ESS': 'Exact canonical source-set retention ESS', 'VSSR': 'Valid source substitution VSSR', 'AA': 'Sufficient support AA'}

def get(group, view, m, kind='scope_count'):
    return next((r for r in est if r['group'] == group and r['view'] == view and (r['metric'] == m) and (r['group_type'] == kind)))
globalrows = []
for m in metrics:
    r = get('all', 'audit_HT', m)
    globalrows.append([labels[m], num(r['estimate']), pct(float(r['estimate']) / 1366), num(r['audit_design_se']), f"{num(r['audit_design_95_low'])}–{num(r['audit_design_95_high'])}"])
L = ['# DeepSeek 1.0.4 terminal-union statistical report', '', 'Version: 2026-10-15. All 136 complex-case adjudications and 120 simple-proxy sample reviews are complete. Following author confirmation, source fields were corrected in 4 of the 74 directly reused records. No reviewed/reused records remain unresolved. This is an English translation of the accompanying Chinese report; numeric table cells are retained.', '', '## 1. Conclusions and scope', '', 'This report measures retention of target claims and their sources within the frozen terminal set; it is not final-answer accuracy. It covers only DeepSeek 1.0.4, chain, original_protocol: 40 2Wiki questions and 20 MuSiQue questions, two repetitions per question/condition, 520 observations and 1366 terminal-by-truth-claim units. Older M versions, Qwen and other topologies are excluded.', '', 'The primary HT estimates are 75.18% complete equivalent expression, 63.95% exact canonical source-set retention, 3.91% valid substitution and 67.86% sufficient support from current sources. These are finite-panel estimates combining exact human evidence and stratified sample expansion, not 1366 individually finalized human judgments.', '', 'Across conditions, M has lower terminal semantic-retention point estimates than B0/B1. In 2Wiki, A1 source masking separates retained semantics from missing citations. M–A2 differences are smaller and estimator-dependent. These are descriptive judgments, not evidence of universal communication effects or statistically significant advantages/disadvantages.', '', '## 2. Denominators and terminal boundaries', '', table(['Component', 'Count', 'Treatment'], [['Direct reuse of existing human evidence', '74', 'Mapping of identical observed content; author corrected 4 union source fields in this round'], ['Complete review of complex cases', '136', 'Itemwise human adjudication, weight 1'], ['Simple-proxy population', '1156', 'Frozen sample from 12 strata'], ['Actually sampled', '120', 'Itemwise human results, expanded by N_h/n_h'], ['Not sampled', '1036', 'Statistical estimation only; no itemwise labels written back'], ['Total with itemwise evidence', '330', '74+136+120; the unweighted mean of these 330 items is not the population estimate'], ['Total', '1366', '210 exact items + 1156 simple-proxy population']]), '', 'M/A1/A2 observe only the two final communication-layer outputs; B1 observes three independent initial-read outputs; B0 observes its single centralized output. B0 contributes 322 single-node scopes and the multi-node view 1044 scopes. Historical initial-read messages are not added to terminal sets. Relevant expressions across nodes and their actual citations undergo union-alignment review.', '', '## 3. Primary population estimates', '', table(['Metric', 'Estimated count', 'Percentage of 1366 (%)', 'Audit-design SE (count)', 'Approximate 95% audit-design interval (count)'], globalrows), '', 'CSR, ESS, VSSR and AA all use every truth scope as denominator. VSSR includes source-set changes that retain canonical sources while adding valid sources, not just complete replacement. AA does not imply each citation is independently sufficient and is distinct from content truth.', '', table(['Mutually exclusive support outcome', 'HT estimated count', 'Percentage (%)'], [[m, num(s['global']['audit_HT'][m]), pct(s['global']['audit_HT'][m] / 1366)] for m in ['ClaimDropped', 'SourceMissing', 'FullSupport', 'PartialSupport', 'NotSupport']]), '', 'ClaimDropped means no complete equivalent expression at the terminal, including partial/absent cases; it does not prove a loss occurred on an edge. Zero PartialSupport and NotSupport estimates mean neither outcome was assigned in the exact/sample evidence, not that they are impossible in the 1036 unreviewed records. Disposition is a workflow field, not CSR; full field distributions are in the data tables.', '', '## 4. Human observations and simple-proxy expansion', '', table(['Component', 'Denominator', 'CSR count', 'ESS count', 'VSSR count', 'AA count'], [[name, str(den)] + [num(next((r['count'] for r in layers if r['layer'] == key and r['metric'] == m))) for m in metrics] for key, name, den in [('direct_reuse_74', 'Direct reuse, exact', 74), ('mandatory_136', 'Complex cases, complete review, exact', 136), ('sample_observed_120', 'Sampled observations, exact', 120), ('simple_population_estimated_1156', 'Simple population, expanded estimate', 1156), ('unreviewed_estimated_1036', 'Unsampled portion, expanded estimate', 1036)]]), '', 'For stratum population N_h, sample size n_h and human outcome indicator y_i:', '', '- Simple-population estimate: Σ_h (N_h/n_h) Σ_{i∈s_h} y_i.', '- Total terminal estimate: 74 reused + 136 completely reviewed complex items + the simple-population estimate.', '- Unsampled-part estimate: Σ_h (N_h/n_h−1) Σ_{i∈s_h} y_i.', '', 'For ESS, the exact part is 66+52=118, the simple-population estimate is 755.5625 and the total is 873.5625. The 79 ESS observations among the 120 sampled items are already included in 755.5625 and are not added again. The estimated ESS count in the 1036 unsampled items is 676.5625. Fractions are weighted counts, not fractional human decisions.', '', table(['Sampling stratum', 'Population N', 'Sample n', 'Unreviewed', 'Expansion weight'], [[r['stratum'], r['population_n'], r['sample_n'], r['unreviewed_n'], f"{float(r['weight']):.6f}"] for r in allocation]), '', '## 5. Simple-proxy usability', '', 'Of 120 items, 111 agree completely on nine compared fields (92.50%); agreement weighted by audit strata is ' + pct(s['agreement_all_nine']['weighted_agreement']) + "%. The nine fields are presence, source-marker status, source set, source change, exact-set survival, support, content truth, disposition, and complete alignment. Do not transfer the older node candidates' approximately 99% agreement or interpret 92.59% as each unaudited candidate's correctness probability.", '', table(['Field / metric', 'Agreement / 120', 'Unweighted agreement (%)', 'Weighted agreement (%)'], [[r['field'], r['matched_n'] + ' / ' + r['sample_n'], pct(r['unweighted_agreement']), pct(r['weighted_agreement'])] for r in agree if r['stratum'] == 'all']), '', '9 discrepancies: ' + '、'.join(s['sample_changed_items']) + '. TU-0549 adds an alias expression and an additional source; the other 8 cases correct paragraph references misclassified as missing. Sample presence/CSR agrees, but that does not establish reliable source fields or complete alignment. Misclassified source loss concentrates in MuSiQue; the report retains this systematic risk.', '', '## 6. Condition comparisons: equal-question macro means', '', 'Normalize each observation by its actual truth-claim count, average r1/r2 within question and condition, then weight questions equally. n=40 for 2Wiki and n=20 for MuSiQue; repeated runs and multiple claims are not independent questions. Values below are percentages.', '']
for view, title in [('audit_HT', 'Primary HT question-macro estimate'), ('audit_difference', 'Candidate-assisted difference estimate (sensitivity)')]:
    L += ['### ' + title, '', table(['Dataset', 'Condition', 'CSR', 'ESS', 'VSSR', 'AA'], [[ds, c] + [pct(next((r['mean'] for r in cond if r['dataset'] == ds and r['condition'] == c and (r['view'] == view) and (r['metric'] == m)))) for m in metrics] for ds in ['2wiki', 'musique'] for c in (['M', 'B0', 'B1', 'A1', 'A2'] if ds == '2wiki' else ['M', 'B0', 'B1'])]), '']
L += ['**Retain and explain estimates outside natural bounds.** The 2Wiki B0 HT question-macro CSR is 104.32%; MuSiQue B0 difference-adjusted ESS/AA is 107.17%. These arise from sparse question-level sampling and unconstrained linear expansion/residual correction, not observed success rates above 100%. Difference estimation may also violate bounds such as AA≤CSR. Do not select a favorable view to replace the primary estimate. Condition-scope rates, question macros and question-type breakdowns remain in supplementary tables.', '', 'Paired differences are M minus comparator, in percentage points. The intervals below are between-question bootstrap descriptive intervals with fixed audit weights, not complete confidence intervals incorporating audit-sampling uncertainty.', '', table(['Dataset', 'Contrast', 'CSR difference [interval]', 'ESS difference [interval]', 'AA difference [interval]'], [[ds, c] + [ci(next((r for r in pairs if r['dataset'] == ds and r['comparison'] == c and (r['view'] == 'audit_HT') and (r['metric'] == m))), 'difference', 'question_bootstrap_95_low', 'question_bootstrap_95_high') for m in ['CSR', 'ESS', 'AA']] for ds in ['2wiki', 'musique'] for c in (['M-B0', 'M-B1', 'M-A1', 'M-A2'] if ds == '2wiki' else ['M-B0', 'M-B1'])]), '', 'Negative M–B0/M–B1 point estimates have the same direction in both estimation views, but several HT between-question intervals cross zero and estimates are unstable; do not describe them as significant decreases. A1 source masking reduces citation metrics by design and alone does not establish the effectiveness of source-maintenance prompting. Small M–A2 differences do not support strong conclusions.', '', '## 7. Candidate sensitivity and bounds for unknown outcomes', '', table(['View', 'CSR（%）', 'ESS（%）', 'VSSR（%）', 'AA（%）'], [[v] + [pct(s['global'][v][m] / 1366) for m in metrics] for v in s['global']]), '', 'All candidate sensitivity views anchor on 210 exact results; no complete old union-candidate set exists for the 136 complex cases. candidate_anchored uses all simple candidates; sample_replaced replaces only sampled items; audit_difference adjusts the complete simple-candidate total using weighted sampled residuals. Sensitivity of source metrics indicates that direct candidate use underestimates citation retention and sufficient support. Unsampled records remain candidates.', '', table(['Metric', 'Lower bound: all unreviewed set to 0 (%)', 'Upper bound: all unreviewed set to 1 (%)'], [[m, pct(float(next((r['lower'] for r in bounds if r['group_type'] == 'scope_count' and r['group'] == 'all' and (r['metric'] == m)))) / 1366), pct(float(next((r['upper'] for r in bounds if r['group_type'] == 'scope_count' and r['group'] == 'all' and (r['metric'] == m)))) / 1366)] for m in metrics]), '', 'These are separate conservative ranges per metric, constrained by the 330 reviewed/reused records and making no accuracy assumption for the 1036 unreviewed records; they are not probabilistic intervals.', '', '## 8. Uncertainty and writing boundaries', '', 'Audit-design intervals treat the frozen panel as the population. They assume simple random sampling without replacement within strata, treating fixed SHA ordering as pseudorandom selection. Variance is Σ_h N_h²(1−n_h/N_h)s_h²/n_h; difference estimates use human-minus-candidate residuals. For macro means and paired contrasts, each scope first receives the appropriate coefficient before this formula is applied.', '', 'Between-question intervals resample whole questions within dataset-by-question-type strata, using 5000 replicates and seed 20261015. All conditions and repetitions of a question remain together, and human-audit weights remain fixed. These intervals and audit-design intervals answer different questions; neither covers all unknown human-judgment bias. They cannot be added or selectively called an overall confidence interval. MuSiQue 4hop/2 contains only one question and therefore has no within-stratum between-question bootstrap variation.', '', 'All-zero/all-one sampled indicators produce zero empirical variance. For example, sampled CSR agrees with the proxy, so residual design standard errors may be zero; this does not prove absence of population error. Complete high-risk review is exact only for the frozen risk route and does not guarantee no complex case escaped into simple proxies. Authors viewed candidates, so this is neither blind review nor independent double-review agreement.', '', 'This report performs no confirmatory significance testing and reports no p-values or Holm conclusions. Earlier manuscript claims of three repetitions or a complete experimental panel must become two repetitions and the actual frozen exploratory scope. Failure-worst and cross-model inference were not performed.', '', '## 9. Statistical methods and results wording for the paper', '', 'Within the frozen DeepSeek 1.0.4 panel, truth claims in offline terminal sets form the measurement units: 60 questions, 520 condition runs and 1366 terminal truth scopes. Existing human evidence for equivalent observed content was directly reused for 74 scopes; 136 high-risk scopes were reviewed individually. The remaining 1156 simple-proxy scopes were divided into 12 dataset/condition/proxy-type strata, from which 120 were reviewed. Population metrics combine the exact portion with stratified Horvitz–Thompson expansion. Unsampled scopes receive no itemwise human labels. Condition comparisons average two repetitions within questions before equal-question macro aggregation and paired contrasts. Candidate-assisted difference estimates, between-question bootstrap intervals at fixed audit weights and finite-population audit-design standard errors describe estimation sensitivity.', '', 'In this finite panel, primary estimates of terminal complete equivalent expression, exact canonical source-set retention, valid substitution and sufficient support from current sources are 75.18%, 63.95%, 3.91% and 67.86%. In the simple-proxy sample, 111/120 items agree on all nine comparison fields; semantic completeness agrees throughout, while nine items differ in alignment or source-related fields. These results motivate separate evaluation of semantic retention and source verifiability. Weighted small-domain estimates are unstable in some conditions, precluding confirmatory significance or cross-panel generalization claims.', '', '## 10. File index and integrity', '', '- `observed_and_expanded_counts.csv`: exact review, simple-population and unsampled-part estimates.', '- `estimates_and_audit_uncertainty.csv`: population, condition, question-type and paired estimates, including design SEs and approximate intervals.', '- `condition_question_macro.csv`, `paired_condition_differences.csv`: between-question bootstrap descriptive intervals.', '- `simple_proxy_agreement.csv`, `simple_proxy_disagreements.json`: sample agreement and nine discrepancies.', '- `terminal_analysis_ledger.jsonl`: identities and evidence levels for 1366 scopes; unreviewed judgment=null.', '- `human_terminal_judgments_256.jsonl`: M2 analysis representation of human forms, not registered into the older node/edge final-review registry.', '- `observation_metrics.csv`, `question_metrics.csv`: traceable analysis tables; HT question values are estimated contributions, not observed success rates.', '- `unreviewed_worst_case_bounds.csv`, `sampling_allocation.csv`: conservative bounds and sample design.', '- `manifest.json`, `verification.json`: input/output hashes and independent verification.', '', 'Four union-reuse corrections are separately recorded in `union_reuse_author_corrections_20261015.json` in the original audit directory. Old node files and frozen candidates were not rewritten. The six unresolved items reported in `completion_20261015` are a historical snapshot; the final forms and this report supersede that status.', '']
(P / 'TERMINAL_UNION_STATISTICS_REPORT.md').write_text('\n'.join(L), encoding='utf-8')
S = ['# Terminal-union supplementary statistical tables', '', 'Intervals below distinguish approximate audit-design intervals from fixed-weight between-question bootstrap intervals. Percentages and percentage-point values are not clipped.', '']
for kind in ['scope_rate', 'question_macro', 'paired_macro_difference', 'question_stratum_macro']:
    S += ['## ' + kind, '', table(['Group', 'View', 'Metric', 'Estimate (% or percentage points)', 'Audit-design SE', 'Approximate 95% audit-design interval'], [[r['group'], r['view'], r['metric'], pct(r['estimate']), pct(r['audit_design_se']) if r['audit_design_se'] else 'NA', f"[{pct(r['audit_design_95_low'])}, {pct(r['audit_design_95_high'])}]" if r['audit_design_95_low'] else 'NA'] for r in est if r['group_type'] == kind and r['metric'] in metrics]), '']
(P / 'SUPPLEMENTARY_TABLES.md').write_text('\n'.join(S), encoding='utf-8')
print('Reports written.')
